from PIL import Image
import numpy as np
from math import floor

PADDED_QR_CODE = Image.open("test_qr_code.png")

scale = 1

while PADDED_QR_CODE.getpixel((4*scale, 4*scale)) == (255,255,255):
    scale += 1

unpadded_width = int(PADDED_QR_CODE.width / scale)
UNSCALED_PADDED_QR_CODE = Image.new(PADDED_QR_CODE.mode, (unpadded_width, unpadded_width), (0, 0, 0))

for x in range(unpadded_width):
    for y in range(unpadded_width):
        pixel = PADDED_QR_CODE.getpixel((scale*x,scale*y))
        UNSCALED_PADDED_QR_CODE.putpixel((x,y), pixel)

VAR_QR_SIZE = UNSCALED_PADDED_QR_CODE.width - 8
QR_CODE = UNSCALED_PADDED_QR_CODE.crop((4, 4, VAR_QR_SIZE + 4, VAR_QR_SIZE + 4))
QR_CODE_VERSION = int((VAR_QR_SIZE - 17) / 4)


