    FORMAT_INFORMATION[0] += '1' if invert != (QR_CODE.getpixel(coords[0]) == (0, 0, 0)) else '0'
    FORMAT_INFORMATION[1] += '1' if invert != (QR_CODE.getpixel(coords[1]) == (0, 0, 0)) else '0'

